69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Basic syntactic email check: a non-empty local part, an '@', and a domain containing at least
73	     * one dot, with no whitespace anywhere. Deliberately permissive but requires the essential shape.
74	     */
75	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
76	
77	    /** Dedicated audit logger; create side-effects are recorded here so they can be observed independently. */
78	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
79	
80	    private final ClinicService clinicService;
81	
82	    private final OwnerMapper ownerMapper;
83	
84	    private final PetMapper petMapper;
85	
86	    private final VisitMapper visitMapper;
87	
88	    public OwnerRestControllerV1(ClinicService clinicService,
89	                                 OwnerMapper ownerMapper,
90	                                 PetMapper petMapper,
91	                                 VisitMapper visitMapper) {
92	        this.clinicService = clinicService;
93	        this.ownerMapper = ownerMapper;
94	        this.petMapper = petMapper;
95	        this.visitMapper = visitMapper;
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
101	        Collection<Owner> owners;
102	        if (lastName != null) {
103	            owners = this.clinicService.findOwnerByLastName(lastName);
104	        } else {
105	            owners = this.clinicService.findAllOwners();
106	        }
107	        if (owners.isEmpty()) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        List<OwnerDto> ownerDtos = owners.stream()
111	            .map(this::toOwnerDtoWithBulkWarning)
112	            .toList();
113	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
119	        Owner owner = this.clinicService.findOwnerById(ownerId);
120	        if (owner == null) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        return new ResponseEntity<>(toOwnerDtoWithBulkWarning(owner), HttpStatus.OK);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
129	        List<String> missingFields = new ArrayList<>();
130	        requireNonBlank(missingFields, "firstName", ownerFieldsDto.getFirstName());
131	        requireNonBlank(missingFields, "lastName", ownerFieldsDto.getLastName());
132	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
133	        requireNonBlank(missingFields, "address", normalizedAddress);
134	        requireNonBlank(missingFields, "city", ownerFieldsDto.getCity());
135	        requireNonBlank(missingFields, "telephone", ownerFieldsDto.getTelephone());
136	        if (!missingFields.isEmpty()) {
137	            throw new MissingRequiredFieldsException(missingFields);
138	        }
139	        LocalDate suppliedOrDefaultDate = ownerFieldsDto.getRegistrationDate() != null
140	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
141	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
142	        requireDailyLimitNotReached(registrationDate);
143	        requireCityBelowCapacity(ownerFieldsDto.getCity());
144	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
145	        ownerFieldsDto.setTelephone(normalizedTelephone);
146	        if (ownerFieldsDto.getEmail() != null) {
147	            ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
148	        }
149	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
150	        HttpHeaders headers = new HttpHeaders();
151	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
152	        owner.setAddress(normalizedAddress);
153	        owner.setRegistrationDate(registrationDate);
154	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
155	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
156	        if (sharesHousehold) {
157	            owner.setHouseholdId(householdIdFor(normalizeForHousehold(owner.getLastName()),
158	                householdAddressKey(owner.getAddress())));
159	        }
160	        requireUniqueIdentity(owner);
161	        if (sharesHousehold) {
162	            backfillHousehold(owner.getLastName(), owner.getAddress(), owner.getHouseholdId());
163	        }
164	        this.clinicService.saveOwner(owner);
165	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={}",
166	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
167	            ownerMapper.toMembershipLevel(owner));
168	        OwnerDto ownerDto = toOwnerDtoWithBulkWarning(owner);
169	        headers.setLocation(UriComponentsBuilder.newInstance()
170	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
171	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
172	    }
173	
174	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
175	    @Override
176	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
177	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
178	        if (currentOwner == null) {
179	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
180	        }
181	        currentOwner.setAddress(ownerFieldsDto.getAddress());
182	        currentOwner.setCity(ownerFieldsDto.getCity());
183	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
184	        currentOwner.setLastName(ownerFieldsDto.getLastName());
185	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
186	        this.clinicService.saveOwner(currentOwner);
187	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
188	    }
189	
190	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
191	    @Transactional
192	    @Override
193	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
194	        Owner owner = this.clinicService.findOwnerById(ownerId);
195	        if (owner == null) {
196	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
197	        }
198	        this.clinicService.deleteOwner(owner);
199	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
200	    }
201	
202	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
203	    @Override
204	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
205	        Owner owner = this.clinicService.findOwnerById(ownerId);
206	        if (owner == null) {
207	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
