209	        HttpHeaders headers = new HttpHeaders();
210	        Pet pet = petMapper.toPet(petFieldsDto);
211	        owner.setId(ownerId);
212	        pet.setOwner(owner);
213	        pet.getType().setName(null);
214	        this.clinicService.savePet(pet);
215	        PetDto petDto = petMapper.toPetDto(pet);
216	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
