221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Override
223	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
224	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
225	        if (currentOwner != null) {
226	            Pet currentPet = this.clinicService.findPetById(petId);
227	            if (currentPet != null) {
228	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
229	                currentPet.setName(petFieldsDto.getName());
230	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
231	                this.clinicService.savePet(currentPet);
232	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
233	            }
234	        }
235	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
236	    }
237	
238	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
239	    @Override
240	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
241	        HttpHeaders headers = new HttpHeaders();
242	        Visit visit = visitMapper.toVisit(visitFieldsDto);
243	        Pet pet = new Pet();
244	        pet.setId(petId);
245	        visit.setPet(pet);
246	        this.clinicService.saveVisit(visit);
247	        VisitDto visitDto = visitMapper.toVisitDto(visit);
248	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
249	            .buildAndExpand(visit.getId()).toUri());
250	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
251	    }
252	
253	
254	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
255	    @Override
256	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
257	        Owner owner = this.clinicService.findOwnerById(ownerId);
258	        if (owner != null) {
259	            Pet pet = owner.getPet(petId);
260	            if (pet != null) {
261	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
262	            }
263	        }
264	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
265	    }
266	
267	    /**
268	     * Builds the owner's customer code as {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the
269	     * upper-cased first three letters of {@code city}, {@code LAST3} the upper-cased first three letters
270	     * of {@code lastName}, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more
271	     * than the number of owners already in that city (e.g. {@code SYD-SMI-0007}).
272	     *
273	     * @param city the owner's city (already validated non-blank)
274	     * @param lastName the owner's last name (already validated non-blank)
275	     * @return the formatted customer code for the owner being created
276	     */
277	    private String nextCustomerCode(String city, String lastName) {
278	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
279	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
280	        int sequence = (int) this.clinicService.findAllOwners().stream()
281	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
282	            .count() + 1;
283	        return String.format("%s-%s-%04d", city3, last3, sequence);
284	    }
285	
286	    /**
287	     * Counts the existing owners (those already persisted before this create) whose first and last
288	     * names both match the incoming owner's, compared case-insensitively. This snapshot is stored on
289	     * the new owner as its {@code namesakeCount} and echoed back on reads.
290	     *
291	     * @param firstName the incoming owner's first name (already validated non-blank)
292	     * @param lastName the incoming owner's last name (already validated non-blank)
293	     * @return the number of existing namesakes sharing both names case-insensitively
294	     */
295	    private int countNamesakes(String firstName, String lastName) {
296	        return (int) this.clinicService.findAllOwners().stream()
297	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
298	                && lastName.equalsIgnoreCase(existing.getLastName()))
299	            .count();
300	    }
301	
302	    /**
303	     * Records {@code fieldName} as missing when {@code value} is {@code null} or blank (empty or
304	     * whitespace-only), so the caller can reject the request listing every offending field.
305	     */
306	    private static void requireNonBlank(List<String> missingFields, String fieldName, String value) {
307	        if (value == null || value.isBlank()) {
308	            missingFields.add(fieldName);
309	        }
310	    }
311	
312	    /**
313	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
314	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
315	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
316	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
317	     * {@code "+61412345678"}.
318	     *
319	     * @param telephone the raw telephone value from the request
320	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
321	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
322	     */
323	    private static String normalizeTelephone(String telephone) {
324	        String e164 = toE164(telephone);
325	        if (e164 == null) {
326	            throw new InvalidFieldValueException("telephone",
327	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
328	        }
329	        return e164;
330	    }
331	
332	    /**
333	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
334	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
335	     * owners' stored numbers when detecting duplicates.
336	     */
337	    private static String toE164(String telephone) {
338	        if (telephone == null) {
339	            return null;
340	        }
341	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
342	        String digits;
343	        if (cleaned.startsWith("+")) {
344	            digits = cleaned.substring(1);
345	        } else {
346	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
347	            digits = "61" + national;
348	        }
349	        if (!digits.matches("[0-9]{8,15}")) {
350	            return null;
351	        }
352	        if (!hasValidNationalLength(digits)) {
353	            return null;
354	        }
355	        return "+" + digits;
356	    }
357	
358	    /**
359	     * Checks the national-number length against the country code for the country codes that pin one.
360	     * A {@code '+61'} (Australia) number must carry exactly 9 national digits and a {@code '+1'}
361	     * (NANP) number exactly 10; every other country code is accepted on the general 8-to-15-digit
362	     * rule alone. {@code digits} is the E.164 digit string without the leading {@code '+'}.
363	     */
364	    private static boolean hasValidNationalLength(String digits) {
365	        if (digits.startsWith("61")) {
366	            return digits.length() - 2 == 9;
367	        }
368	        if (digits.startsWith("1")) {
369	            return digits.length() - 1 == 10;
370	        }
371	        return true;
372	    }
373	
374	    /**
375	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
376	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
377	     *
378	     * @param email the raw email value from the request (already known to be non-null)
379	     * @return the lower-cased email to be stored and returned
380	     * @throws InvalidFieldValueException if the value is not a syntactically valid email address
381	     */
382	    private static String normalizeEmail(String email) {
383	        String trimmed = email.trim();
384	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
385	            throw new InvalidFieldValueException("email", "Email must be a syntactically valid address");
386	        }
387	        return trimmed.toLowerCase(Locale.ROOT);
388	    }
389	
390	    /** The maximum number of owners permitted in a single city; the {@code (50 + 1)}th is rejected. */
391	    private static final int MAX_OWNERS_PER_CITY = 50;
392	
393	    /**
394	     * Rejects the request when the owner's city already contains {@link #MAX_OWNERS_PER_CITY} or more
395	     * owners, comparing city names case-insensitively (consistent with the per-city customer-code
396	     * sequence). Callers reach this only once {@code city} has been validated non-blank.
397	     *
398	     * @param city the incoming owner's city (already validated non-blank)
399	     * @throws CityAtCapacityException if the city is already at or above its owner capacity
400	     */
401	    /** The maximum number of owners that may be registered in a single day; the {@code (100 + 1)}th is rejected. */
402	    private static final int MAX_OWNERS_PER_DAY = 100;
403	
404	    /**
405	     * Rejects the request when {@link #MAX_OWNERS_PER_DAY} or more owners have already been registered
406	     * on {@code businessDay}, counting existing owners whose {@code registrationDate} equals that date.
407	     * New owners take {@code businessDay} as their {@code registrationDate} (the supplied or defaulted
408	     * date rolled forward to a business day), so this caps the number that may be created per day.
409	     *
410	     * @param businessDay the adjusted business-day registration date of the owner being created
411	     * @throws DailyOwnerLimitException if the daily owner-creation limit has already been reached
412	     */
413	    /**
414	     * The number of owners for a single day beyond which the {@code bulkSignupWarning} flag is
415	     * raised; the warning is true once <em>more than</em> this many owners share a registration date.
416	     */
417	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
418	
419	    /**
420	     * Maps {@code owner} to its DTO and sets the {@code bulkSignupWarning} flag: {@code true} when
421	     * more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for this
422	     * owner's registration date, otherwise {@code false}.
423	     *
424	     * @param owner the owner to map
425	     * @return the owner DTO with its bulk-signup warning flag populated
426	     */
427	    private OwnerDto toOwnerDtoWithBulkWarning(Owner owner) {
428	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
429	        ownerDto.setBulkSignupWarning(exceedsBulkSignupThreshold(owner.getRegistrationDate()));
430	        return ownerDto;
431	    }
432	
433	    /**
434	     * Returns whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
435	     * created on {@code registrationDate}, counting existing owners whose {@code registrationDate}
436	     * equals that date. Returns {@code false} when {@code registrationDate} is {@code null}.
437	     */
438	    private boolean exceedsBulkSignupThreshold(LocalDate registrationDate) {
439	        if (registrationDate == null) {
440	            return false;
441	        }
442	        long registeredThatDay = this.clinicService.findAllOwners().stream()
443	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
444	            .count();
445	        return registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
446	    }
447	
448	    private void requireDailyLimitNotReached(LocalDate businessDay) {
449	        long registeredThatDay = this.clinicService.findAllOwners().stream()
450	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
451	            .count();
452	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
453	            throw new DailyOwnerLimitException(MAX_OWNERS_PER_DAY);
454	        }
455	    }
456	
457	    /**
458	     * Rolls {@code date} forward to a business day: when it falls on a Saturday or Sunday it advances
459	     * to the following Monday; a weekday is returned unchanged. Applied to the effective registration
460	     * date (whether supplied in the request or defaulted to the server date) so a weekend registration
461	     * is recorded on the next business day, and every value derived from the registration date uses the
462	     * adjusted date.
463	     *
464	     * @param date the effective registration date (supplied or defaulted), never {@code null}
465	     * @return the same date, or the next Monday when {@code date} is a weekend
466	     */
467	    private static LocalDate toBusinessDay(LocalDate date) {
468	        DayOfWeek day = date.getDayOfWeek();
469	        if (day == DayOfWeek.SATURDAY) {
470	            return date.plusDays(2);
471	        }
472	        if (day == DayOfWeek.SUNDAY) {
473	            return date.plusDays(1);
474	        }
475	        return date;
476	    }
477	
478	    private void requireCityBelowCapacity(String city) {
479	        long cityOwners = this.clinicService.findAllOwners().stream()
480	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
481	            .count();
482	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
483	            throw new CityAtCapacityException(city);
484	        }
485	    }
486	
487	    /**
488	     * Rejects the request when the incoming owner's derived {@code identityKey} exactly matches that
489	     * of any existing owner. The key ({@code normalizedTelephone + '|' + (email or empty) + '|' +
490	     * (householdId or empty)}) is the single consolidated duplicate-detection key that replaces the
491	     * former separate telephone, email and household checks. Because the telephone is part of the
492	     * key, two members of the same household (same {@code householdId}) with different telephones
493	     * have different keys and are both allowed; only an exact full-key match is a duplicate. The key
494	     * is derived identically for the incoming and existing owners via {@link OwnerMapper#toIdentityKey}.
495	     *
496	     * @param owner the incoming owner, with its normalized telephone, email and household identifier
497	     *              already populated
498	     * @throws DuplicateIdentityException if another owner already has this exact identity key
499	     */
500	    private void requireUniqueIdentity(Owner owner) {
501	        String identityKey = ownerMapper.toIdentityKey(owner);
502	        boolean taken = this.clinicService.findAllOwners().stream()
503	            .map(ownerMapper::toIdentityKey)
504	            .anyMatch(identityKey::equals);
505	        if (taken) {
506	            throw new DuplicateIdentityException(identityKey);
507	        }
508	    }
509	
510	    /**
511	     * Normalizes a value for household-duplicate comparison: trims leading and trailing whitespace,
512	     * collapses every internal run of whitespace to a single space, and lower-cases the result so
513	     * comparisons are case-insensitive.
514	     */
515	    private static String normalizeForHousehold(String value) {
516	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
517	    }
518	
519	    /**
520	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
521	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
522	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
523	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
524	     * value normalizes to the empty string, so the required-field check rejects an address that is
525	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
526	     *
527	     * @param address the raw address value from the request (may be {@code null})
528	     * @return the normalized address, or the empty string when blank after normalization
529	     */
530	    private static String normalizeAddress(String address) {
531	        if (address == null) {
532	            return "";
533	        }
534	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
535	        if (collapsed.isEmpty()) {
536	            return "";
537	        }
538	        String[] tokens = collapsed.split(" ");
539	        StringBuilder sb = new StringBuilder();
540	        for (String token : tokens) {
541	            String expanded = switch (token) {
542	                case "ST" -> "STREET";
543	                case "RD" -> "ROAD";
544	                case "AVE" -> "AVENUE";
545	                default -> token;
546	            };
547	            if (sb.length() > 0) {
548	                sb.append(' ');
549	            }
550	            sb.append(expanded);
551	        }
552	        return sb.toString();
553	    }
554	
555	    /**
556	     * Derives the comparison key for an address used by household-duplicate detection and the shared
557	     * household identifier: the address is first put in its canonical normalized form and then
558	     * lower-cased and whitespace-collapsed, so every comparison and the derived id agree on the
559	     * normalized address regardless of the raw casing, spacing or abbreviations supplied.
560	     */
561	    private static String householdAddressKey(String address) {
562	        return normalizeForHousehold(normalizeAddress(address));
563	    }
564	
565	    /**
566	     * Back-fills the shared {@code householdId} onto every existing member of the household
567	     * identified by this last name and address (same normalized last name and address) that does not
568	     * already carry it, so the whole household agrees on the identifier. Members that predate this
569	     * feature (or were created without opting in) are updated to the shared value. Called only after
570	     * the joining owner has passed the identity check, so a rejected request leaves existing owners
571	     * untouched.
572	     *
573	     * @param lastName the joining owner's last name (already validated non-blank)
574	     * @param address the joining owner's address (already validated non-blank)
575	     * @param householdId the shared household identifier for this last name and address
576	     */
577	    private void backfillHousehold(String lastName, String address, String householdId) {
578	        String normalizedLastName = normalizeForHousehold(lastName);
579	        String normalizedAddress = householdAddressKey(address);
580	        this.clinicService.findAllOwners().stream()
581	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
582	                && householdAddressKey(existing.getAddress()).equals(normalizedAddress))
583	            .filter(existing -> !householdId.equals(existing.getHouseholdId()))
584	            .forEach(existing -> {
585	                existing.setHouseholdId(householdId);
586	                this.clinicService.saveOwner(existing);
587	            });
588	    }
589	
590	    /**
591	     * Derives a stable household identifier from the already-normalized last name and address as the
592	     * upper-cased first 12 hex characters of their SHA-256 digest. Deterministic so the same household
593	     * always maps to the same identifier.
594	     */
595	    private static String householdIdFor(String normalizedLastName, String normalizedAddress) {
596	        try {
597	            byte[] digest = MessageDigest.getInstance("SHA-256")
598	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
599	            StringBuilder sb = new StringBuilder();
600	            for (byte b : digest) {
601	                sb.append(String.format("%02X", b));
602	            }
603	            return sb.substring(0, 12);
604	        }
605	        catch (NoSuchAlgorithmException e) {
606	            throw new IllegalStateException("SHA-256 not available", e);
607	        }
608	    }
609	}
