    /**
     * Handles {@link InvalidFieldValueException} raised when a request supplies a field whose value
     * is present but violates a business rule (for example a telephone number that is not exactly
     * ten digits after stripping non-digit characters). Returns a 400 Bad Request whose body carries
     * an {@code errors} array listing the name of each offending field.
     *
     * @param e The {@link InvalidFieldValueException} to be handled
     * @param request {@link HttpServletRequest} object referring to the current request.
     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
     */
    @ExceptionHandler(InvalidFieldValueException.class)
    @ResponseBody
    public ResponseEntity<ProblemDetail> handleInvalidFieldValueException(InvalidFieldValueException e, HttpServletRequest request) {
        HttpStatus status = HttpStatus.BAD_REQUEST;
        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
        detail.setProperty("errors", e.getFields());
        logger.debug("Invalid field value at {} {}: {}",
            request.getMethod(),
            request.getRequestURI(),
            e.getFields());
        return ResponseEntity.status(status).body(detail);
    }

    /**
     * Handles {@link DuplicateIdentityException} raised when a request attempts to create an owner
     * whose derived {@code identityKey} (normalized telephone, email and household identifier joined
     * by {@code '|'}) exactly matches that of an existing owner. This single key consolidates the
     * former separate telephone, email and household duplicate checks. Returns a 409 Conflict whose
     * body carries an {@code errors} array naming the offending field.
     *
     * @param e The {@link DuplicateIdentityException} to be handled
     * @param request {@link HttpServletRequest} object referring to the current request.
     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
     */
    @ExceptionHandler(DuplicateIdentityException.class)
    @ResponseBody
    public ResponseEntity<ProblemDetail> handleDuplicateIdentityException(DuplicateIdentityException e, HttpServletRequest request) {
        HttpStatus status = HttpStatus.CONFLICT;
        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
        detail.setProperty("errors", e.getFields());
        logger.debug("Duplicate identity at {} {}: {}",
            request.getMethod(),
            request.getRequestURI(),
            e.getFields());
        return ResponseEntity.status(status).body(detail);
    }

    /**
     * Handles {@link CityAtCapacityException} raised when a request attempts to create an owner
     * whose city already contains the maximum number of owners (50 or more). Returns a 409 Conflict
     * whose body carries an {@code errors} array naming the offending field.
     *
     * @param e The {@link CityAtCapacityException} to be handled
     * @param request {@link HttpServletRequest} object referring to the current request.
     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
     */
    @ExceptionHandler(CityAtCapacityException.class)
    @ResponseBody
    public ResponseEntity<ProblemDetail> handleCityAtCapacityException(CityAtCapacityException e, HttpServletRequest request) {
        HttpStatus status = HttpStatus.CONFLICT;
        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
        detail.setProperty("errors", e.getFields());
        logger.debug("City at capacity at {} {}: {}",
            request.getMethod(),
            request.getRequestURI(),
            e.getFields());
        return ResponseEntity.status(status).body(detail);
    }

    /**
     * Handles {@link DailyOwnerLimitException} raised when a request attempts to create an owner
     * once the maximum number of owners for the current day (100 or more, by {@code registrationDate})
     * has already been reached. Returns a 429 Too Many Requests.
     *
     * @param e The {@link DailyOwnerLimitException} to be handled
     * @param request {@link HttpServletRequest} object referring to the current request.
     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
     */
    @ExceptionHandler(DailyOwnerLimitException.class)
    @ResponseBody
    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitException(DailyOwnerLimitException e, HttpServletRequest request) {
        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
        logger.debug("Daily owner limit reached at {} {}",
            request.getMethod(),
            request.getRequestURI());
        return ResponseEntity.status(status).body(detail);
    }

}

